function browserDumpDom(browserPath, url, { timeoutMs = 25000, signal } = {}) {
  return new Promise((resolve) => {
    // 独立 user-data-dir：避免与用户正在运行的浏览器实例抢同一 profile（共享 profile 时无输出/立即退出）
